function photoForPlace(name,city,idx=0){const match=attractionPhotos.find(([pattern])=>pattern.test(name));const text=String(name).toLowerCase();const category=/temple|mosque|church|shrine|cathedral|pagoda|stupa/.test(text)?'photo-1548013146-72479768bada':/beach|coast|island|waterfront|lake|river|ghat|waterfall|falls|bay/.test(text)?'photo-1507525428034-b723cf961d3e':/fort|palace|castle|tomb|monument|heritage|ruins|archaeological|cave/.test(text)?'photo-1564507592333-c60657eea523':/museum|gallery|library|art/.test(text)?'photo-1561214115-f2f134cc4912':/garden|park|zoo|forest|hill|mountain|viewpoint|valley|nature|botanical/.test(text)?'photo-1470770841072-f978cf4d019e':/market|bazaar|food|street|quarter|village|walk|promenade/.test(text)?'photo-1517248135467-4c7edcad34c4':null;const id=match?match[1]:(category||destinationPhotos[city]||images[idx%images.length]);return `https://images.unsplash.com/${id}?auto=format&fit=crop&w=700&q=82`; }
// Prefer the actual attraction's Wikipedia thumbnail; use a relevant subject photo only if unavailable.
function resolvePlacePhoto(img,name,placeContext,backup){const title=String(name||'').replace(/\s+/g,' ').trim();if(!title)return;const key=title.toLowerCase().replace(/[^a-z0-9]/g,'');if(img.dataset.photoResolved===key)return;img.dataset.photoResolved=key;const fallback=photoForPlace(title,placeContext,0)||backup||img.src;const candidates=[title,`${title} ${placeContext||''}`.trim()];(async()=>{for(const q of candidates){try{const r=await fetch('https://en.wikipedia.org/api/rest_v1/page/summary/'+encodeURIComponent(q.replace(/ /g,'_')),{headers:{accept:'application/json'}});if(!r.ok)continue;const d=await r.json();if(d.thumbnail&&d.thumbnail.source){img.src=d.thumbnail.source;img.dataset.photoActual='1';return;}}catch(e){}}img.src=fallback;})();}
function bindPlacePhotos(root){root.querySelectorAll('img[data-place-photo]').forEach(img=>resolvePlacePhoto(img,img.dataset.placePhoto,img.dataset.placeContext,img.dataset.backup));}
