function initCities(){const names=Object.keys(cityData).sort();["origin","destination"].forEach(id=>{const s=$(id);s.innerHTML=names.map(n=>`<option value="${n}">${n}, ${cityData[n].state}</option>`).join("");});$("origin").value="Vijayawada";$("destination").value="Hyderabad";}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function money(n){return new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(n);}
function mapURL(query,embed=false,mode='road'){const layer=mode==='satellite'?'k':'m';return embed?`https://maps.google.com/maps?q=${encodeURIComponent(query)}&z=13&t=${layer}&output=embed`:`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;}
function setYatriqMap(frameId,linkId,query,mode='road'){const frame=$(frameId),link=$(linkId);if(!frame||!link)return;frame.dataset.mapQuery=query;frame.dataset.mapMode=mode;const nextSrc=mapURL(query,true,mode);if(frame.src!==nextSrc)frame.src=nextSrc;link.href=mapURL(query);document.querySelectorAll(`[data-map-frame="${frameId}"]`).forEach(button=>{button.classList.toggle('is-active',button.dataset.mapView===mode);button.setAttribute('aria-pressed',String(button.dataset.mapView===mode));});}
function placeScore(place,tags,interests){const text=(place+" "+tags.join(" ")).toLowerCase();return interests.reduce((n,i)=>n+((interestsMap[i]||[]).some(k=>text.includes(k))?2:0),0);}
function selectedPlaces(city,interests,budget,days){const d=cityData[city],perDay=days>=5?3:4;let arr=d.places.map((name,i)=>({name,tags:d.tags[i],score:placeScore(name,d.tags[i],interests),idx:i})).sort((a,b)=>b.score-a.score);if(!interests.length)arr=d.places.map((name,i)=>({name,tags:d.tags[i],score:0,idx:i}));const perPerson=budget/Number($("travellers").value||1);if(perPerson<4000)arr=arr.filter(p=>!p.tags.includes("Premium"));return arr.slice(0,Math.min(d.places.length,Math.max(4,days*perDay)));}
function timeFor(i){return [{time:"7:00–9:00 AM",label:"Early start",why:"Cooler weather and a calmer start; ideal for viewpoints, outdoor walks and sunrise spots."},{time:"9:30 AM–12:00 PM",label:"Explore",why:"A good window for major landmarks and heritage sites. Confirm opening times before leaving."},{time:"12:00–2:00 PM",label:"Lunch & reset",why:"Take a break during the warmer hours and try a well-reviewed local restaurant."},{time:"2:30–5:00 PM",label:"Culture & discovery",why:"Choose museums, indoor attractions or a second nearby landmark to avoid unnecessary backtracking."},{time:"5:00–7:00 PM",label:"Golden hour",why:"Best suited to waterfronts, gardens and viewpoints when local conditions permit."},{time:"7:00–9:00 PM",label:"Dinner & local life",why:"Finish with regional food or a market area; check safe transport back to your stay."}][i%6];}
function renderHotels(city,budget,days,travellers,style){const perNight=Math.max(500,Math.round(budget/(days*Math.max(1,travellers))*.36));const tiers=[{name:"Smart budget stay",type:"Guesthouses · hostels · basic hotels",base:900,desc:"Best for stretching your budget and spending more on experiences."},{name:"Comfort pick",type:"Well-rated 2–3 star options",base:2200,desc:"A balance of convenience, privacy and comfort."},{name:"Premium stay",type:"Boutique · upscale hotels",base:5200,desc:"More amenities and a higher-comfort experience when the budget allows."}];let pick=style==="budget"?0:style==="comfort"?1:style==="premium"?2:perNight<1600?0:perNight<3800?1:2;const budgetPerNight=budget/(days*Math.max(1,travellers));const allowed=tiers.filter((t,i)=>t.base<=Math.max(1200,budgetPerNight*1.35)||i===0);if(!allowed.some(t=>t.name===tiers[pick].name))pick=allowed.length?tiers.indexOf(allowed[allowed.length-1]):0;return tiers.map((t,i)=>({ ...t,selected:i===pick,available:t.base<=Math.max(1500,budgetPerNight*1.45)||i===0,estimate:Math.round(t.base*(cityData[city].state==="Goa"||city==="Mumbai"?1.2:1))}));}
function renderPlan(e){e.preventDefault();const origin=$("origin").value,dest=$("destination").value,days=Math.max(1,Math.min(30,Number($("days").value)||1)),budget=Math.max(5000,Number($("budget").value)||5000),travellers=Math.max(1,Math.min(20,Number($("travellers").value)||1)),style=$("style").value,interests=[...document.querySelectorAll('input[name="interest"]:checked')].map(x=>x.value);$("budget").value=budget;const city=cityData[dest],places=selectedPlaces(dest,interests,budget,days);const perPerson=budget/travellers,perDay=budget/days;const transport=Math.round(budget*.25),stay=Math.round(budget*.35),food=Math.round(budget*.23),activities=budget-transport-stay-food;
$("tripSummary").innerHTML=`<div class="summary-item"><small>YOUR ROUTE</small><strong>${esc(origin)} → ${esc(dest)}</strong><span>${esc(city.state)} · ${esc(city.mood)}</span></div><div class="summary-item"><small>DURATION</small><strong>${days} ${days===1?"day":"days"}</strong><span>${travellers} traveller${travellers===1?"":"s"}</span></div><div class="summary-item"><small>TOTAL BUDGET</small><strong>${money(budget)}</strong><span>${money(perPerson)} per person · ${money(perDay)}/day</span></div><div class="summary-item"><small>TRAVEL MOOD</small><strong>${interests.length?interests.map(x=>({history:"Culture",nature:"Nature",food:"Food",adventure:"Adventure",relax:"Relax",shopping:"Shopping"}[x])).join(" · "):"A little of everything"}</strong><span>Personalized for your choices</span></div>`;
const budgetItems=[ ["Intercity & local transport",transport,"Transport can vary substantially by mode and booking time."],["Accommodation",stay,"Assumes budget-aware stays; room sharing changes the per-person cost."],["Food & refreshments",food,"Mix local eateries with occasional sit-down meals."],["Activities & buffer",activities,"Entry fees, small experiences and unexpected costs."] ];$("budgetBreakdown").innerHTML=budgetItems.map(([n,v,d])=>`<div class="budget-row"><div class="budget-row-top"><strong>${n}</strong><b>${money(v)}</b></div><div class="budget-track"><span style="width:${Math.max(0,v/budget*100)}%"></span></div><small>${esc(d)}</small></div>`).join("");const estimateOneWay=Math.round(500+Math.abs(Object.keys(cityData).indexOf(origin)-Object.keys(cityData).indexOf(dest))*85),estimateRoundTrip=estimateOneWay*2*travellers,remainingAfterTransport=budget-estimateRoundTrip;$("nationalCostSummary").innerHTML=`<div class="national-cost-stat"><small>TOTAL GROUP BUDGET</small><strong>${money(budget)}</strong><span>${money(perPerson)} per traveller</span></div><div class="national-cost-stat"><small>ROUND-TRIP TRANSPORT ESTIMATE</small><strong>${money(estimateRoundTrip)}</strong><span>For ${travellers} traveller${travellers===1?"":"s"}</span></div><div class="national-cost-stat"><small>ACCOMMODATION ALLOCATION</small><strong>${money(stay)}</strong><span>${Math.max(0,days-1)} night${days-1===1?"":"s"} planning envelope</span></div><div class="national-cost-stat ${remainingAfterTransport<0?'cost-overrun':''}"><small>${remainingAfterTransport<0?'TRANSPORT OVER BUDGET':'BUDGET AFTER TRANSPORT'}</small><strong>${money(Math.abs(remainingAfterTransport))}</strong><span>${remainingAfterTransport<0?'Estimated fare exceeds the trip budget':'Before stays, food and activities'}</span></div>`;$("budgetNote").textContent=`Estimated total for ${travellers} traveller${travellers===1?"":"s"}. ${money(perPerson)} per person across the trip. ${budget<days*travellers*1500?"This is a tight budget for the duration: consider fewer days, public transport and shared budget stays.":"Keep a small emergency reserve and verify live costs before booking."}`;
const list=$("itineraryList");list.innerHTML="";const placesPerDay=days>=5?3:4;for(let day=0;day<days;day++){const chosen=places.slice(day*placesPerDay,day*placesPerDay+placesPerDay);const article=document.createElement("article");article.className="day-card";article.innerHTML=`<div class="day-number">${String(day+1).padStart(2,"0")}<small>DAY ${day+1}</small></div><div class="day-content"><div class="day-title-row"><div><h4>${day===0?`Arrive in ${esc(dest)}`:day===days-1?`A final day in ${esc(dest)}`:`${esc(dest)} highlights · Day ${day+1}`}</h4><p class="day-intro">${day===0?`Travel from ${esc(origin)} and settle into your stay. Keep arrival-day plans flexible.`:day===days-1?"Leave enough time for checkout and your return journey.":`A paced route around ${esc(city.mood.toLowerCase())}, grouped to keep the day manageable.`}</p></div></div><div class="schedule-list">${chosen.map((p,i)=>{const t=timeFor(i+(day===0?1:0));return `<button class="schedule-stop" type="button" data-place="${esc(p.name)}"><span class="stop-time">${t.time}</span><span class="stop-photo"><img data-place-photo="${esc(p.name)}" data-place-context="${esc(dest)}" data-backup="${photoForPlace(p.name,dest,p.idx)}" src="${photoForPlace(p.name,dest,p.idx)}" alt="${esc(p.name)}" loading="lazy" onerror="this.onerror=null;this.src=this.dataset.backup;this.classList.add('image-fallback')"></span><span class="stop-main"><strong>${esc(p.name)}</strong><small>${esc(p.tags.join(" · "))}</small><span class="visit-tip">${esc(t.why)}</span></span><span class="stop-arrow">↗</span></button>`;}).join("")}</div><p class="day-footer">Suggested pace · Check exact opening hours and travel time before departure.</p></div>`;list.appendChild(article);bindPlacePhotos(article);}
const hotels=renderHotels(dest,budget,days,travellers,style);$("hotelGrid").innerHTML=hotels.map((h,i)=>`<article class="hotel-card ${h.selected?"hotel-selected":""}"><div class="hotel-icon">${["⌂","✧","◇"][i]}</div><div class="hotel-topline">${h.selected?'<span class="selected-label">BEST FIT FOR THIS PLAN</span>':`<span class="hotel-category">${i===0?"VALUE":"OPTION"}</span>`}</div><h4>${h.name}</h4><p class="hotel-type">${h.type}</p><p>${h.desc}</p><div class="hotel-price"><strong>~${money(h.estimate)}</strong><small>/ room / night, indicative</small></div><p class="hotel-area">Suggested area: ${esc(city.stay)}.</p><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(h.name+" in "+dest+" "+city.state)}">Find stays on Google Maps ↗</a></article>`).join("");
$("cityMapTitle").textContent=dest+", "+city.state;setYatriqMap("cityMap","cityMapLink",dest+", "+city.state+", India");const first=places[0]?.name||dest;selectPlace(first,dest);$("travelTips").innerHTML=`<div class="tips-icon">✦</div><div><div class="eyebrow">LOCAL KNOW-HOW</div><h3>When to go, and how to get around</h3><p><strong>Timing:</strong> Outdoor sights and viewpoints are usually more comfortable early morning or late afternoon. Schedule museums and indoor heritage sites for hotter midday hours, but verify each attraction's own opening days and hours.</p><p><strong>Best way to move:</strong> Compare train/bus options for intercity travel and use metro, local buses, walking or app-based taxis within the city where available. For short city hops, open the selected place in Google Maps and choose Directions to compare live routes and traffic.</p><p><strong>Season:</strong> Weather varies by region; check a reliable forecast and local advisories for your travel dates.</p></div>`;
$("results").hidden=false;}
function selectPlace(name,city){const query=name+", "+city+", India";$("placeMapTitle").textContent=name;setYatriqMap("placeMap","placeMapLink",query,$("placeMap").dataset.mapMode||"road");}
form.addEventListener("submit",renderPlan);$("editPlan").addEventListener("click",()=>{$("results").hidden=true;});document.addEventListener("click",e=>{const stop=e.target.closest(".schedule-stop");if(stop){const query=stop.dataset.place+", "+$("destination").value+", India";selectPlace(stop.dataset.place,$("destination").value);window.open(mapURL(query),"_blank","noopener,noreferrer");}const dest=e.target.closest(".destination-card");if(dest){$("destination").value=dest.dataset.destination;}});
function renderDestinationCards(){const featured=["Jaipur","Goa","Varanasi","Udaipur","Visakhapatnam","Kochi","Delhi","Mysuru","Hyderabad","Shimla","Amritsar","Agra"];$("destinationGrid").innerHTML=featured.map((city,i)=>`<button class="destination-card" type="button" data-destination="${city}"><img src="${city==='Mysuru'?'https://commons.wikimedia.org/wiki/Special:FilePath/Mysore_Palace_Image.jpg?width=900':`https://images.unsplash.com/${destinationPhotos[city]||images[i%images.length]}?auto=format&fit=crop&w=800&q=85`}" alt="Explore ${city}" loading="lazy" onerror="this.onerror=null;this.src='https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80';this.classList.add('image-fallback')"><span class="dest-number">${String(i+1).padStart(2,"0")} / ${esc(cityData[city].state.toUpperCase())}</span><span class="dest-info"><strong>${esc(city)}</strong><small>${esc(cityData[city].mood)}</small><i>↗</i></span></button>`).join("");}
