$('profileForm').addEventListener('submit',e=>{e.preventDefault();const files=['passport','visa'].map(k=>$('profileForm').elements[k]?.files?.[0]).filter(Boolean);$('profileStatus').textContent=`Demo profile saved for ${$('profileForm').elements.fullName.value}. ${files.length} file(s) selected locally; nothing was uploaded and documents were not verified.`;});
