function openPayment(label,amount){$('paymentSummary').textContent=`${label} · ${money(amount)} estimated total.`;$('paymentQR').src='assets/payment-qr.jpg';$('bookingQR').src='assets/payment-qr.jpg';$('qrArea').hidden=false;$('bookingQrArea').hidden=true;$('paymentSuccessOverlay').hidden=true;$('paymentMethodForm').hidden=true;$('completeDemoPayment').hidden=false;$('paymentStatus').textContent='';openModal('paymentModal');}
$('completeDemoPayment').addEventListener('click',()=>{$('paymentStatus').textContent='Demo payment successful! Your sample booking is not a real reservation and no money was charged.';});
// Existing India hotel cards now offer selectable demo checkout, and return transport estimates are shown.
const oldRenderPlan=renderPlan;
renderPlan=function(e){oldRenderPlan(e);const origin=$('origin').value,dest=$('destination').value,days=Math.max(1,Number($('days').value)||1),travellers=Math.max(1,Number($('travellers').value)||1),budget=Math.max(5000,Number($('budget').value)||5000);const route=document.createElement('div');route.className='roundtrip-panel';const oneWay=Math.round(500+Math.abs(Object.keys(cityData).indexOf(origin)-Object.keys(cityData).indexOf(dest))*85);route.innerHTML=`<div><div class="eyebrow">ROUND-TRIP TRANSPORT · ESTIMATE</div><h3>${esc(origin)} ⇄ ${esc(dest)}</h3><p>Indicative bus/train estimate per traveller; compare actual routes and availability before booking.</p></div><div class="roundtrip-fares"><span>Outbound <b>${money(oneWay)}</b></span><span>Return <b>${money(oneWay)}</b></span><span>Round trip · ${travellers} traveller(s) <b>${money(oneWay*2*travellers)}</b></span></div><button class="button primary" type="button" id="indiaDemoCheckout">Select hotel & demo checkout ↗</button>`;const stay=$('hotelGrid');stay.parentNode.insertBefore(route,stay);route.querySelector('#indiaDemoCheckout').addEventListener('click',()=>{const selected=stay.querySelector('.hotel-selected h4')?.textContent||'Smart budget stay';openPayment(`${dest} stay · ${selected}`,budget);});stay.querySelectorAll('.hotel-card').forEach((card,i)=>{if(!card.querySelector('.hotel-book')){const btn=document.createElement('button');btn.type='button';btn.className='button quiet hotel-book';btn.textContent='Choose this stay';btn.addEventListener('click',()=>{stay.querySelectorAll('.hotel-card').forEach(c=>c.classList.remove('hotel-selected'));card.classList.add('hotel-selected');stay.querySelectorAll('.hotel-book').forEach(b=>b.textContent='Choose this stay');btn.textContent='Selected stay ✓';});card.appendChild(btn);}});};
function attachIndiaCheckout(){const origin=$('origin').value,dest=$('destination').value,travellers=Math.max(1,Number($('travellers').value)||1),budget=Math.max(5000,Number($('budget').value)||5000);document.querySelectorAll('.roundtrip-panel').forEach(n=>n.remove());const oneWay=Math.round(500+Math.abs(Object.keys(cityData).indexOf(origin)-Object.keys(cityData).indexOf(dest))*85);const route=document.createElement('div');route.className='roundtrip-panel';route.innerHTML=`<div><div class="eyebrow">ROUND-TRIP TRANSPORT · ESTIMATE</div><h3>${esc(origin)} ⇄ ${esc(dest)}</h3><p>Indicative bus/train estimate per traveller; compare actual routes and availability before booking.</p></div><div class="roundtrip-fares"><span>Outbound <b>${money(oneWay)}</b></span><span>Return <b>${money(oneWay)}</b></span><span>Round trip · ${travellers} traveller(s) <b>${money(oneWay*2*travellers)}</b></span></div><button class="button primary" type="button" id="indiaDemoCheckout">Select hotel & demo checkout ↗</button>`;const stay=$('hotelGrid');stay.parentNode.insertBefore(route,stay);route.querySelector('#indiaDemoCheckout').addEventListener('click',()=>openPayment(`${dest} stay · ${stay.querySelector('.hotel-selected h4')?.textContent||'Smart budget stay'}`,budget));stay.querySelectorAll('.hotel-card').forEach(card=>{if(!card.querySelector('.hotel-book')){const btn=document.createElement('button');btn.type='button';btn.className='button quiet hotel-book';btn.textContent='Choose this stay';btn.addEventListener('click',()=>{stay.querySelectorAll('.hotel-card').forEach(c=>c.classList.remove('hotel-selected'));card.classList.add('hotel-selected');stay.querySelectorAll('.hotel-book').forEach(b=>b.textContent='Choose this stay');btn.textContent='Selected stay ✓';});card.appendChild(btn);}});}
form.addEventListener('submit',()=>setTimeout(attachIndiaCheckout,80));

// Accessible map-view controls work for both static and dynamically rendered map panels.
document.addEventListener('click',e=>{const button=e.target.closest('[data-map-view][data-map-frame]');if(!button)return;e.preventDefault();button.focus({preventScroll:true});const frame=document.getElementById(button.dataset.mapFrame),link=document.getElementById(button.dataset.mapLink);if(!frame)return;const query=frame.dataset.mapQuery;if(!query){if(link&&link.href)window.open(link.href,'_blank','noopener,noreferrer');return;}if(button.dataset.mapView==='3d'){const url='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(query)+'&basemap=satellite';window.open(url,'_blank','noopener,noreferrer');return;}setYatriqMap(button.dataset.mapFrame,button.dataset.mapLink,query,button.dataset.mapView);});

// YATRIQ multi-view experience: landing page, national agent and international agent.
// Refined YATRIQ cursor: minimal deep-green pointer with a subtle soft edge.
(function installPremiumCursor(){
 if(document.getElementById('yatriq-premium-cursor-style')) return;
 const svg='<svg xmlns="http://www.w3.org/2000/svg" width="28" height="32" viewBox="0 0 28 32"><path d="M4 3 L4 25 L10 19 L15 29 L19 27 L14 17 L23 17 Z" fill="#244c3d" stroke="#fffdf5" stroke-width="1.7" stroke-linejoin="round"/><path d="M4 3 L4 25 L10 19 L15 29 L19 27 L14 17 L23 17 Z" fill="none" stroke="#244c3d" stroke-width=".7" stroke-linejoin="round"/></svg>';
 const uri='data:image/svg+xml,'+encodeURIComponent(svg);const style=document.createElement('style');style.id='yatriq-premium-cursor-style';style.textContent='@media (pointer:fine){html,body{cursor:url("'+uri+'") 4 3,auto}a,button,[role="button"],input,select,textarea,label{cursor:pointer}}';document.head.appendChild(style);
})();
(function(){
 const $=id=>document.getElementById(id);let activeTrip='';let profileSaved={national:false,international:false};
 const sections=['planner','results','country-trips','explore','multi-city'];
 function setView(view){document.body.dataset.view=view;if(window.renderYatriqReviews)window.renderYatriqReviews(view);sections.forEach(id=>{const el=$(id);if(el)el.hidden=true;});const hero=document.querySelector('.hero');const closing=document.querySelector('.closing-cta');const isHome=view==='home';hero.hidden=!isHome;if(closing)closing.hidden=true;
  if(view==='multi'){if($('multi-city'))$('multi-city').hidden=false;if($('multiCityResults')&&!$('multiCityResults').innerHTML.trim())$('multiCityResults').hidden=true;}
  else if(view==='national'){['planner','explore'].forEach(id=>{if($(id))$(id).hidden=false;});if($('results') && !document.getElementById('itineraryList').children.length)$('results').hidden=true;else if($('results'))$('results').hidden=false;}
  else if(view==='international'){$('country-trips').hidden=false;}
  else {}
 }
 // The landing view is intentionally uncluttered; allow the standalone multi-tour URL to open directly.
 const requestedView=new URLSearchParams(window.location.search).get('view');
 setView(requestedView==='multi'?'multi':'home');
 $('planMyTrip')?.addEventListener('click',()=>openModal('tripTypeModal'));
 $('exploreCountries')?.addEventListener('click',()=>{setView('international');});
 $('brandHome')?.addEventListener('click',e=>{e.preventDefault();activeTrip='';setView('home');});
 document.querySelectorAll('a[href="#planner"]').forEach(link=>link.addEventListener('click',e=>{e.preventDefault();openModal('tripTypeModal');}));
 document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{const view=b.dataset.view;if(view==='national'){activeTrip='national';setView('national');}else if(view==='multi'){activeTrip='multi';setView('multi');}else{activeTrip='international';setView('international');}}));
 document.querySelectorAll('[data-choose-trip]').forEach(b=>b.addEventListener('click',()=>{activeTrip=b.dataset.chooseTrip;closeModal('tripTypeModal');if(activeTrip==='multi'){setView('multi');return;}setView(activeTrip);openProfile(activeTrip)}));
 function openProfile(type){activeTrip=type;const profileType=type==='multi'?'national':type;$('loginTitle').innerHTML=profileType==='national'?'Traveller details <em>for your trip.</em>':'International traveller <em>details.</em>'; const fields=$('profileFields');const common='<label class="field"><span>Full name</span><input name="fullName" required placeholder="Enter your full name" autocomplete="name"></label><label class="field"><span>Email address</span><input name="email" type="email" required placeholder="you@example.com" autocomplete="email"></label><label class="field"><span>Phone number</span><input name="phone" type="tel" required placeholder="Contact number" autocomplete="tel"></label>';
  if(profileType==='national'){fields.innerHTML=common+'<label class="field"><span>Aadhaar card number (demo)</span><input name="aadhaar" inputmode="numeric" pattern="[0-9]{12}" maxlength="12" required placeholder="12-digit demo number"></label><p class="small-note">Privacy note: use a fictional 12-digit number for this demo. It is not verified, uploaded or stored.</p>';}
  else{fields.innerHTML=common+'<label class="field"><span>Passport picture (demo)</span><input name="passport" type="file" accept="image/*,.pdf" required></label><label class="field"><span>Visa approval picture (demo)</span><input name="visa" type="file" accept="image/*,.pdf" required></label><p class="small-note">Use sample files only. Documents remain local and are not uploaded or verified.</p>';}
  $('profileStatus').textContent='';openModal('loginModal');
 }
 document.querySelectorAll('.login-trigger').forEach(b=>{b.onclick=()=>{if(!activeTrip){openModal('tripTypeModal')}else openProfile(activeTrip)}});
 $('profileForm').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const name=data.get('fullName');profileSaved[activeTrip]=true;const files=['passport','visa'].map(k=>data.get(k)).filter(f=>f instanceof File&&f.name);$('profileStatus').textContent=`Demo details saved for ${name}. No identity verification or upload took place.`;closeModal('loginModal');if(activeTrip==='national'){setView('national');$('tripForm').classList.add('agent-ready');}else if(activeTrip==='multi'){setView('multi');}else{setView('international');$('countrySelect')?.focus({preventScroll:true});} });
 // Payment uses the supplied QR image only; no UPI-ID or card form is shown.
 window.openPayment=function(label,amount){$('paymentSummary').textContent=`${label} · ${money(amount)} estimated total.`;$('paymentQR').src='assets/payment-qr.jpg';$('bookingQR').src='https://api.qrserver.com/v1/create-qr-code/?size=300x300&margin=12&data='+encodeURIComponent(new URL('assets/congratulations-image.png',window.location.href).href);$('qrArea').hidden=false;$('bookingQrArea').hidden=true;$('paymentSuccessOverlay').hidden=true;$('paymentMethodForm').hidden=true;$('completeDemoPayment').hidden=false;$('paymentStatus').textContent='';openModal('paymentModal');};
 $('completeDemoPayment').addEventListener('click',()=>{$('paymentMethodForm').hidden=true;$('qrArea').hidden=true;$('bookingQrArea').hidden=true;$('paymentStatus').textContent='';$('paymentSuccessOverlay').hidden=false;window.clearTimeout(window.yatriqSuccessTimer);window.yatriqSuccessTimer=window.setTimeout(()=>{if(!$('paymentModal').hidden){$('paymentSuccessOverlay').hidden=true;$('bookingQrArea').hidden=false;}},1800);});
 $('closeSuccessPayment')?.addEventListener('click',()=>{window.clearTimeout(window.yatriqSuccessTimer);closeModal('paymentModal');$('paymentSuccessOverlay').hidden=true;$('bookingQrArea').hidden=true;$('qrArea').hidden=false;});
 // Country-card clicks stay within the international agent and never scroll from the landing page.
 const countryGrid=$('countryGrid');countryGrid?.addEventListener('click',()=>{activeTrip='international'});
 // Hide legacy content on first load and style the separate agent views consistently.
})();
